(function () {
      var workspace = document.querySelector("[data-finance-workspace]");
      if (!workspace) return;
      var filters = Array.prototype.slice.call(workspace.querySelectorAll("[data-finance-filter]"));
      var cards = Array.prototype.slice.call(workspace.querySelectorAll("[data-finance-status]"));
      var packetButtons = Array.prototype.slice.call(workspace.querySelectorAll("button[data-packet-title]"));
      var title = workspace.querySelector("[data-packet-title]:not(button)");
      var status = workspace.querySelector("[data-packet-status]:not(button)");
      var body = workspace.querySelector("[data-packet-body]:not(button)");
      var missing = workspace.querySelector("[data-packet-missing]");
      var route = workspace.querySelector("[data-packet-route]");

      filters.forEach(function (filter) {
        filter.addEventListener("click", function () {
          var value = filter.dataset.financeFilter;
          filters.forEach(function (item) { item.classList.remove("is-active"); });
          filter.classList.add("is-active");
          cards.forEach(function (card) {
            var show = value === "all" || card.dataset.financeStatus === value;
            card.hidden = !show;
          });
        });
      });

      packetButtons.forEach(function (button) {
        button.addEventListener("click", function () {
          title.textContent = button.dataset.packetTitle || "";
          status.textContent = button.dataset.packetStatus || "";
          body.textContent = button.dataset.packetBody || "";
          missing.textContent = button.dataset.packetMissing || "";
          route.textContent = button.dataset.packetRoute || "";
        });
      });
    }());
